    // ========== v23.79：店小秘跨域查询（GM_xmlhttpRequest，ERP 内直接查店小秘成本） ==========
    // 突破点验证：HTTP 200 + code=0 msg=Successful → Cookie 跨站携带成功、接口联通（2026-09-09 实测）
    // 店小秘成功码是 code=0（不是 200）；searchPackage 拿订单信息，出入记录拿成本（Σ|变动|×新单价，包材=名称含【包材】）
    const _win = (typeof unsafeWindow !== 'undefined') ? unsafeWindow : window;
    // v24.50：请求令牌桶 —— 实测无间隔连发第 4 次即返回 code=2005「系统繁忙」，400ms 间隔稳定通过；
    //   容量 3 + 2.5 次/秒补充：单次查询（2~4 个请求）几乎无感，批量则自动被限到安全速率。
    const DXM_RL_CAP = 3;
    const DXM_RL_RATE = 2.5;      // 令牌/秒
    let _dxmTokens = DXM_RL_CAP;
    let _dxmTokenAt = Date.now();
    async function dxmTakeToken() {
        for (;;) {
            const now = Date.now();
            _dxmTokens = Math.min(DXM_RL_CAP, _dxmTokens + (now - _dxmTokenAt) / 1000 * DXM_RL_RATE);
            _dxmTokenAt = now;
            if (_dxmTokens >= 1) { _dxmTokens -= 1; return; }
            const wait = Math.ceil((1 - _dxmTokens) / DXM_RL_RATE * 1000) + 40;
            await new Promise(r => setTimeout(r, wait));
        }
    }
    // v24.50：店小秘限流（code=2005）自动重试 —— 退避 0.9s / 1.8s / 2.7s，最多 3 次
    async function dxmRequest(method, url, data) {
        let last = null;
        for (let attempt = 0; attempt < 4; attempt++) {
            await dxmTakeToken();
            const r = await dxmRequestOnce(method, url, data);
            last = r;
            const busy = r && r.ok !== false && (r.code === 2005 || (r.msg && /繁忙|稍后重试/.test(String(r.msg))));
            if (!busy) return r;
            if (attempt < 3) {
                const wait = 900 * (attempt + 1);
                console.warn('店小秘限流（code=2005），' + wait + 'ms 后重试（第 ' + (attempt + 1) + '/3 次）');
                await new Promise(r2 => setTimeout(r2, wait));
            }
        }
        return last;
    }
    function dxmRequestOnce(method, url, data) {
        return new Promise((resolve) => {
            try {
                GM_xmlhttpRequest({
                    method: method, url: url,
                    headers: {
                        'Content-Type': 'application/x-www-form-urlencoded',
                        'Accept': 'application/json, text/plain, */*',
                        'Origin': 'https://www.dianxiaomi.com',
                        'Referer': 'https://www.dianxiaomi.com/web/order/all?go=m1-1'
                    },
                    data: data, timeout: 20000,
                    onload: (r) => {
                        try { const j = JSON.parse(r.responseText); resolve({ ok: true, status: r.status, code: j.code, msg: j.msg, data: j.data }); }
                        catch (e) { resolve({ ok: true, status: r.status, raw: r.responseText }); }
                    },
                    onerror: (err) => resolve({ ok: false, error: String(err) }),
                    ontimeout: () => resolve({ ok: false, timeout: true })
                });
            } catch (e) { resolve({ ok: false, error: 'GM_xmlhttpRequest 不可用: ' + e.message }); }
        });
    }
