    //   缓存：localStorage['sb_kdocs_online_v1']，24h 过期；每次进页面后台刷新；失败静默回退内置表（不阻塞、不报错）。
    const KDOCS_DOCS = [
        { sid: 'ciOfXuCYP13s', fileid: '561931226610', type: 'pack' },   // 定制包装登记
        { sid: 'ckUhsnaj7fsA', fileid: '561933779460', type: 'vat' }     // 发货渠道物流税率登记
    ];
    // v24.59：**分享 ID 可覆盖** —— 金山文档被重新分享 / 另存 / 移动到别处时，`/l/{sid}` 会变，
    //   旧 sid 请求 session 接口会返回 403 + result="InvalidVersion"（实测：pack 文档曾如此，vat 仍正常）。
    //   以前只能改脚本常量；现在用户自己就能修：
    //     控制台执行  __setKdocsDoc('pack', 'https://www.kdocs.cn/l/xxxx')  然后刷新页面
    //     （localStorage 键 sb_kdocs_docs_v1 = {"pack":"新sid","vat":"..."}，直接整条链接粘贴也可以）
    const KDOCS_SID_KEY = 'sb_kdocs_docs_v1';
    function kdocsSidOf(type, def) {
        try {
            const raw = localStorage.getItem(KDOCS_SID_KEY);
            if (!raw) return def;
            const o = JSON.parse(raw) || {};
            const v = o[type];
            if (!v) return def;
            const m = String(v).match(/kdocs\.cn\/l\/([A-Za-z0-9_-]+)/);   // 允许整条分享链接
            return (m ? m[1] : String(v).trim()) || def;
        } catch (e) { return def; }
    }
    KDOCS_DOCS[0].sid = kdocsSidOf('pack', KDOCS_DOCS[0].sid);
    KDOCS_DOCS[1].sid = kdocsSidOf('vat', KDOCS_DOCS[1].sid);
    // 失败时的可操作指引（含当前生效的 sid，便于核对）
    function kdocsFixHint() {
        return '👉 诊断里出现 InvalidVersion（金山拒绝了请求）——两个已知原因与修法：\n'
            + '   ① 手工指定过 front_ver 且与文档版本不符 → 控制台执行 __setKdocsVer("") 清空（默认不发版本号）\n'
            + '   ② 文档分享链接变了 → 打开该文档复制地址栏链接 → __setKdocsDoc("pack", "链接") → 刷新页面\n'
            + '   当前生效：pack=' + KDOCS_DOCS[0].sid + '　vat=' + KDOCS_DOCS[1].sid + '\n'
            + '               front_ver=' + (KDOCS_FRONT_VER || '（未发送）');
    }
    try {
        _win.__kdocsDocs = () => { console.log('金山文档当前分享 ID：pack=' + KDOCS_DOCS[0].sid + ' / vat=' + KDOCS_DOCS[1].sid, KDOCS_DOCS); return KDOCS_DOCS; };
        _win.__setKdocsDoc = (type, val) => {
            if (type !== 'pack' && type !== 'vat') return '用法：__setKdocsDoc("pack", "https://www.kdocs.cn/l/xxxx")（type 支持 pack / vat）';
            const m = String(val || '').match(/kdocs\.cn\/l\/([A-Za-z0-9_-]+)/);
            const sid = (m ? m[1] : String(val || '').trim());
            if (!sid) return '❌ 未识别到分享 ID（请粘贴完整链接，或直接给 /l/ 后面那段）';
            let o = {};
            try { o = JSON.parse(localStorage.getItem(KDOCS_SID_KEY) || '{}') || {}; } catch (e) { }
            o[type] = sid;
            try { localStorage.setItem(KDOCS_SID_KEY, JSON.stringify(o)); } catch (e) { return '❌ 写入失败：' + e; }
            return '✅ 已记住 ' + type + ' = ' + sid + ' → 请刷新页面生效（不想改了可执行 __clearKdocsDoc() 恢复默认）';
        };
        _win.__clearKdocsDoc = () => { try { localStorage.removeItem(KDOCS_SID_KEY); } catch (e) { } return '✅ 已清除自定义分享 ID，刷新后使用脚本内置值'; };
    } catch (e) { }
    // v24.61：⚠️ **不要再发 front_ver**（真根因）——实测（2026-09-17，真实接口交叉验证）：
    //   front_ver 需要与**目标文档各自的版本**一致，而两个文档的版本并不相同：
    //     pack 文档：传 2026-09-01 版 → 403 InvalidVersion；传 2026-09-16 版 → 200
    //     vat  文档：传 2026-09-01 版 → 200；            传 2026-09-16 版 → 403 InvalidVersion
    //   → 只要写死一个值，必然有一个文档拉不到（用户现象：pack 表格更新后抓不到）。
    //   **不传（或传空串）时两个文档都 200**（session 与 open/ksheet 均如此）→ 由服务端按文档当前版本处理。
    //   所以默认留空；万一将来服务端要求带版本，可用控制台 __setKdocsVer('2026...') 临时指定。
    const KDOCS_VER_KEY = 'sb_kdocs_front_ver';
    const KDOCS_FRONT_VER = (function () {
        try { return String(localStorage.getItem(KDOCS_VER_KEY) || '').trim(); } catch (e) { return ''; }
    })();
    try {
        _win.__setKdocsVer = (v) => {
            const s = String(v == null ? '' : v).trim();
            try { if (s) localStorage.setItem(KDOCS_VER_KEY, s); else localStorage.removeItem(KDOCS_VER_KEY); } catch (e) { return '❌ 写入失败：' + e; }
            return s ? ('✅ 已指定 front_ver = ' + s + ' → 刷新页面生效（仅在某文档因此报错时才需要）') : '✅ 已清空 front_ver（默认状态：不发送版本号）';
        };
    } catch (e) { }
    const KDOCS_CACHE_KEY = 'sb_kdocs_online_v2';   // v24.34：解析器修复 —— 换 key 让旧的（不完整）缓存立即失效
    const KDOCS_CACHE_TTL = 24 * 3600 * 1000;   // 24 小时
    // v24.23：以在线为准开关——true：文档抓完整时**整体替换**内置表（文档没登记的条目即失效，含内置独有条目）；
    //   false：退回叠加合并（在线覆盖命中项，内置独有条目保留兜底）。
    //   ⚠️ 替换模式下若文档只是「部分登记」，会有一批内置条目失效——控制台/状态条会列出停用条目数，便于及时发现。
    const KDOCS_ONLINE_AUTHORITATIVE = true;
    const KDOCS_CN2ISO = { '美国': 'US', '阿曼': 'OM', '科威特': 'KW', '墨西哥': 'MX', '越南': 'VN', '沙特阿拉伯': 'SA', '摩洛哥': 'MA', '挪威': 'NO', '智利': 'CL', '斯里兰卡': 'LK', '南非': 'ZA', '阿拉伯联合酋长国': 'AE', '阿联酋': 'AE', '哥伦比亚': 'CO', '萨尔瓦多': 'SV', '泰国': 'TH', '巴林': 'BH' };
    const kdocsGm = (method, url, body, respType) => new Promise((resolve, reject) => {
        // v24.00：伪装来源头——金山 session 接口有 CSRF 防护（非 www.kdocs.cn 来源 → 403 SessionDeleted，HAR 实证请求带
        //   Origin: https://www.kdocs.cn + Referer: https://www.kdocs.cn/l/{sid}）；GM_xmlhttpRequest 允许设置这些头
        // v24.93：⚠️ 必须匿名（anonymous:true 不带浏览器 kdocs.cn Cookie）——
        //   curl 无 Cookie 直打 session/open 全通（2026-09-21 实证），而浏览器 GM 请求默认带着
        //   过期/半失效的金山登录态 Cookie → 服务端走「已登录」分支校验失败 → 403/空 session
        //   →「金山文档加载失败」。匿名化后与验证路径一致（分享链接本身匿名可读）。
        const m = url.match(/\/(?:session|file)\/([^\/]+)\//);
        const ksid = m ? m[1] : '';
        GM_xmlhttpRequest({
            method: method, url: url,
            headers: {
                'Content-Type': 'text/plain;charset=UTF-8',
                'Origin': 'https://www.kdocs.cn',
                'Referer': ksid ? ('https://www.kdocs.cn/l/' + ksid) : 'https://www.kdocs.cn/',
                'Accept': '*/*',
                'Accept-Language': 'zh-CN,zh;q=0.9'
            },
            data: body ? JSON.stringify(body) : undefined,
            responseType: respType || 'text',
            timeout: 15000,
            anonymous: true,
            onload: (r) => resolve(r),
            onerror: (e) => reject(e || new Error('GM_xmlhttpRequest onerror')),
            ontimeout: () => reject(new Error('timeout')),
            onabort: () => reject(new Error('abort'))
        });
    });
