                _kdocsStatusEl.style.cssText = 'position:fixed;top:12px;left:50%;transform:translateX(-50%);z-index:999999;background:#111;color:#fff;padding:10px 18px;border-radius:8px;font:12px/1.6 sans-serif;max-width:86vw;text-align:center;box-shadow:0 2px 14px rgba(0,0,0,.4);opacity:.97;white-space:pre-line;';
                document.body.appendChild(_kdocsStatusEl);
