                const modeTxt = (okPack ? '以在线为准' : '在线未确认完整·叠加') + ' / ' + (okVat ? '以在线为准' : '在线未确认完整·叠加');
                const rowsTxt = '（共读 包材 ' + _prog.pack.rows + ' 行 / 税率 ' + _prog.vat.rows + ' 行）';
                // 停用条目统计（仅替换模式有意义）
