                            _dataVersion++;
                            _meta.count = data.count || 0;
                            _meta.page = data.page || 1;
                            _meta.page_size = data.page_size || getPageSize();
                            _meta.total_pages = data.total_pages || Math.ceil(_meta.count / _meta.page_size);
                            console.log('📦 已缓存数据（XHR），共', data.results.length, '条，page_size:', data.page_size, '总条数:', _meta.count);
