    // ========== 工具函数 ==========
    function toast(msg, type) {
        const existing = document.querySelector('.custom-toast');
        if (existing) existing.remove();

        const div = document.createElement('div');
        div.className = 'custom-toast';
        div.textContent = msg;
        div.style.cssText = `position:fixed;top:20px;left:50%;transform:translateX(-50%);padding:10px 20px;border-radius:4px;z-index:999999;font-size:14px;background:${type === 'error' ? '#f56c6c' : '#67c23a'};color:white;`;
        document.body.appendChild(div);
        setTimeout(() => div.remove(), 3000);
    }

    function fallbackCopy(text) {
        const ta = document.createElement('textarea');
        ta.value = text;
        ta.style.cssText = 'position:fixed;left:-9999px;';
        document.body.appendChild(ta);
        ta.select();
        document.execCommand('copy');
        document.body.removeChild(ta);
        toast('✅ 复制成功！');
    }

    // ========== 从表格提取可见字段（降级） ==========
    function getTableData() {
        const headers = [];
        document.querySelectorAll('.el-table__header-wrapper thead th').forEach(th => {
            const text = th.textContent.trim();
            if (text) headers.push(text);
        });
        const rows = document.querySelectorAll('.el-table__body-wrapper tbody tr:not(.floating-detail-panel)');
        const data = [];
        rows.forEach(tr => {
            const row = {};
            const cells = tr.querySelectorAll('td');
            cells.forEach((td, idx) => {
                const key = headers[idx];
                if (key) row[key] = td.textContent.trim();
            });
            data.push(row);
        });
        return data;
    }

    // ========== v23.51：报价列表 动态数据同步（按可见字段匹配，替代脆弱索引映射） ==========
    function tableHeaders() {
        const h = [];
        document.querySelectorAll('.el-table__header-wrapper thead th').forEach(th => {
            const t = th.textContent.trim();
            if (t) h.push(t);
        });
        return h;
    }
    // 把某 DOM 行与报价数据按可见字段打分匹配：返回 { q, score }
    // 商品计款码不匹配则排除；命中字段越多越可信；未命中返回 q=null
    function matchRowToData(tr, data) {
        if (!data || !data.length) return { q: null, score: 0 };
        const headers = tableHeaders();
        const cells = tr.querySelectorAll('td');
        const vis = {};
        cells.forEach((td, idx) => { const h = headers[idx] || ''; if (h) vis[h] = td.textContent.trim(); });
        let best = { q: null, score: 0 };
        for (const q of data) {
            let s = 0, codeBad = false;
            for (const [h, v] of Object.entries(vis)) {
                if (!v) continue;
                let qv = '';
                if (/计款码|QPN/i.test(h)) qv = String((q.product_code && q.product_code.code) || '');
                else if (/国家/.test(h)) qv = String((q.country && (q.country.chinese_name || q.country.name || q.country.code)) || '');
                else if (/生效时间/.test(h)) qv = String((q.effective_period_from || q.effective_date || q.created_time || '')).slice(0, 10);
                else if (/首件价格/.test(h)) qv = String(q.first_unit_price != null ? q.first_unit_price : '');
                else if (/物流方案|渠道/.test(h)) qv = String((q.shipping_pricing_rule && q.shipping_pricing_rule.name) || '');
                else if (/店铺/.test(h)) qv = String((q.store && q.store.store_code) || '');
                if (!qv) continue;
                if (/计款码|QPN/i.test(h) && v !== qv) { codeBad = true; break; }
                if (v === qv) s++;
            }
            if (codeBad) continue;
            if (s > best.score) best = { q, score: s };
        }
        return best;
    }
    // 当前表格行签名（计款码+国家），用于检测表格变化→动态重建
    function tableSignature() {
        const headers = tableHeaders();
        const tbody = document.querySelector('.el-table__body-wrapper tbody');
        if (!tbody) return '';
        let s = '';
        tbody.querySelectorAll('tr:not(.floating-detail-panel)').forEach(tr => {
            const cells = tr.querySelectorAll('td');
            cells.forEach((td, idx) => {
                const h = headers[idx] || '';
                if (/计款码|QPN/i.test(h) || /国家/.test(h)) s += h + '=' + td.textContent.trim() + '|';
            });
        });
        return s;
    }

    // ========== 字段定义（显示带单位，复制不带单位） ==========
