    function bulkExportCsv() {
        const st = _bulkState;
        if (!st.results.length) { toast('⚠️ 暂无结果可导出', 'warn'); return; }
        const f2 = v => (v == null || v === '' || isNaN(v)) ? '' : (Math.round(v * 100) / 100).toFixed(2);
        const f4 = v => (v == null || v === '' || isNaN(v)) ? '' : (Math.round(v * 10000) / 10000).toFixed(4);   // ★ v25.51：成本列 4 位（v25.47 精度）+ 空值防护——出入记录缺失时 prodCost/packCost 为 null，裸 toFixed 会崩
        const pct = v => (v == null || isNaN(v)) ? '' : (v * 100).toFixed(2) + '%';
        const rows = [BULK_OUT_HEADERS];
        st.results.forEach(x => {
            const b = x.base || {}, v = x.vol || {};
            const thr = (v.threshold != null ? v.threshold : (b.threshold != null ? b.threshold : 0.12));
            // v24.64：卖价与重量口径无关（两种口径同值），优先取实际重口径
            const _sv = k => (b[k] != null ? b[k] : (v[k] != null ? v[k] : null));
            // v24.52：合并列 = 成本模板规则名（形如「渠道|国家」）+ (区间) + (生效日期)；未匹配模板时退回「采用渠道（未匹配模板）」
            const tplRule = String(v.tplRule || b.tplRule || '').trim();
            const tplRange = String(v.tplRange || b.tplRange || '').trim();
            const tplEff = String(v.tplEff || b.tplEff || '').slice(0, 10);
            const chanTpl = tplRule
                ? (tplRule + (tplRange ? '(' + tplRange + ')' : '') + (tplEff ? '(' + tplEff + ')' : ''))
                : ((x.specMethod || x.method || '') + '（未匹配模板）');
            rows.push([
                x.pkg, x.track, x.orderNo || '', x.shipDate || '', (x.shipDateUsed || x.shipDate || ''), x.country || '', (x.clientId || ''), (x.storeUpload || ''), (x.sku || ''),
                f2(x.actualW), f4(x.prodCost), f4(x.packCost), f2(x.declareTotal), (x.declareSrc || ''),
                f2(x.specW != null ? x.specW : x.actualW), x.over ? '是' : '',
                (x.actualW > 0 && x.specW > 0) ? (x.specW / x.actualW).toFixed(2) : '',   // v24.56：体积重倍数
                x.method || '', x.specMethodRaw || '',
                (x.channelKind || (x.actualOnly ? '自定义渠道(无映射)' : '模板匹配')),
                chanTpl,
                f2(v.tplUnit != null ? v.tplUnit : b.tplUnit), f2(v.tplReg != null ? v.tplReg : b.tplReg),
                (function () { const _rs = (v.roundStep || b.roundStep || 0); return _rs > 0 ? f2(_rs) : ''; })(),   // v24.71：进位重kg（空=该渠道不进制）
                f2(_sv('itemSell')), f2(_sv('packSell')), f2(_sv('extraPrice')), (x.sellSource || ''),
                f2(x.billFs), f2(x.billDuty),
                f2(x.taxCny), f2(x.taxBase), (x.taxNote || ''),
                (x.isMulti ? (v.cnt != null ? v.cnt : '') : (x.err ? '' : 1)),
                f2(b.billW != null ? b.billW : x.actualW), f2(b.ship), f2(b.sell), f4(b.cost), pct(b.margin), (b.margin == null ? '' : (b.margin >= thr ? '达标' : '未达标')), pct(b.marginNoTax),
                f2(v.billW != null ? v.billW : (x.specW != null ? x.specW : x.actualW)), f2(v.ship), f2(v.sell), f4(v.cost), pct(v.margin), (v.margin == null ? '' : (v.margin >= thr ? '达标' : '未达标')), pct(v.marginNoTax),
                f2(v.profit != null ? v.profit : x.profitVol),                                   // v24.56：毛利额(按体积重)
                (b.margin != null && v.margin != null) ? ((v.margin - b.margin) * 100).toFixed(2) + '%' : '',
                (x.addNeed > 0 ? f2(x.addNeed) : ''),
                (x.addNeed > 0 && x.addManual != null ? f2(x.addManual) : ''),                    // ★ v25.06：其中需手填（总额 − 欧盟自动）
                (x.addNeed > 0 && x.addPct != null) ? (x.addPct * 100).toFixed(1) + '%' : '',     // v24.56：需加收幅度%
                (x.addNeed > 0 && x.marginAfter != null) ? pct(x.marginAfter) : '',               // ★ v25.06：加收后毛利率（= 按上面总额）
                (x.overImpact || ''),
                // v24.78：云途实际值（未补齐时一律留空，不用模拟值顶替）
                (b.tplCompany || v.tplCompany || ''),
                f2(x.ytWeight), f2(x.ytFreight), f2(x.ytSimCost),
                (x.ytHsCount == null ? '' : String(x.ytHsCount)),
                (x.ytEuTax == null ? '' : f2(x.ytEuTax)),
                (x.ytBaseFreight == null ? '' : f2(x.ytBaseFreight)),
                (x.ytDiff == null ? '' : f2(x.ytDiff)),
                (x.ytStatus || ''), pct(x.realMargin), pct(x.realMarginNoEu),
                (x.actualOnly || (x.base && x.base.marginOnlyActual)) ? '仅实际（渠道未映射）' : (x.realMargin != null ? '模拟+实际' : ''),
                [x.err, x.specMethodWarn, x.cusWarn, x.sellWarn, x.countryWarn, x.clientWarn, x.ytHsWarn].filter(Boolean).join('；'),
                (x.lossDiag || ''), (x.quotUpdate || '')   // ★ v25.52：亏本原因自动诊断 + 报价更新建议
            ]);
        });
        bulkSave('批量模拟结果_' + new Date().toISOString().slice(0, 10) + '.csv', bulkToCsv(rows));
    }
    // ==========================================================================================
    // v24.78：物流商官网（云途 OMS）实际计费重 / 实际运费 接入
    // ------------------------------------------------------------------------------------------
    // 用途：批量模拟跑完后，单独执行「补齐云途实际运费」——按运单号查云途官网的
