    // 物流公司判定：只有真正的云途才去查云途官网
    function yxIsYun(code, name) {
        const c = String(code || '').trim();
        const n = String(name || '').trim();
        if (/FYD|菲易达/i.test(c) || /菲易达/.test(n)) return false;    // 云途代理，不算云途
        if (/^4px/i.test(c) || /遞四方|递四方/.test(n)) return false;    // 递四方-雲途：走 4PX 结算
        if (/^yun$/i.test(c)) return true;
        return /雲途|云途/.test(n);
    }

    // ==========================================================================================
    // v24.86：递四方（4PX）识别 —— 该票货该去哪个物流商官网查？
    // ------------------------------------------------------------------------------------------
    // 递四方有**两个商家账号**，账单按账号隔离（实测：主账号查 Sunny 的运单号返回 total=0，反之亦然），
    // 所以必须先判断「这票货走的是哪个账号」，否则查了也是 0 条，白耗限流配额。
    //   主账号      ← 「递四方-联邮通标准挂号-普货」这类不带 Sunny 的
    //   Sunny 账号 ← 「递四方-Sunny-联邮通经济挂号-普货」这类名称里带 Sunny 的
    // 判定依据（按优先级）：
    //   ① 成本模板的「物流公司」编码/名称（4px / 4px-Yun / 遞四方…）—— 命中模板时最可靠
    //   ② 店小秘物流方式原文 —— 渠道**未映射**到成本模板时唯一的线索（Sunny 渠道就属于这种）
    //   ③ 运单号形态兜底（4PX 开头 + CN 结尾）
    // ==========================================================================================
    const FPX_TRACK_RE = /^4PX\d{6,}CN$/i;
