                    + '<td style="' + TH + 'text-align:right;">' + f2(x.registeredFee) + '</td>'
                    + '<td style="' + TH + 'text-align:right;">' + f2(x.otherFee) + '</td>'
                    + '<td style="' + TH + 'text-align:right;font-weight:600;">' + f2(x.totalFee) + '</td>'
