    // v25.00：返回值加上 **token 来源**（浏览器 cs_token = 自动续期 / 账号设置手填 / 内置）
    function v7AkpsTokenExpText() {
        try {
            const exp = v7JwtExp(_v7AkpsTokenCache);
            const srcTxt = (_v7AkpsTokSrc === 'browser') ? '浏览器会话 cs_token（登官网即自动续期）'
                : (_v7AkpsTokSrc === 'custom') ? '账号设置手填'
                    : (_v7AkpsTokSrc === 'builtin') ? '内置（会过期）' : '';
            if (!exp) return srcTxt;
            const days = Math.ceil((exp - Date.now()) / 86400000);
            return (srcTxt ? 'token 来源：' + srcTxt + '，' : '') + (days > 0 ? ('约 ' + days + ' 天后到期') : '已过期');
        } catch (e) { }
        return '';
    }
