                ylog('  ⬇ 查询第 ' + (Math.floor(i / YX_BATCH) + 1) + '/' + Math.ceil(wbs.length / YX_BATCH) + ' 批（' + part.length + ' 个运单号）…');
                const got = await yxFreightBatch(part);
