            ylog('❌ ' + msg);
            if (/未认证|token/.test(msg)) ylog('   ↳ token 失效或登录被拒：点「🔌 测试连接」看详细原因；确认账号密码正确');
            if (hint) { hint.style.color = '#cf1322'; hint.textContent = '❌ ' + msg; }
            toast('❌ 物流商补齐失败：' + msg, 'error');
