                            _cu.bad.slice(0, 5).forEach(b => bulkLog('   第 ' + b.no + ' 行 ' + b.tag + ' → ' + b.msg));
                            if (_cu.bad.length > 5) bulkLog('   …另有 ' + (_cu.bad.length - 5) + ' 处同类问题');
