            euSell: Math.min((typeof _euApplied !== 'undefined' && _euApplied) ? (_euApplied.sell || 0) : 0, extraPrice), euCost: Math.min((typeof _euApplied !== 'undefined' && _euApplied) ? (_euApplied.cost || 0) : 0, extraCost),   // v25.08：不含税口径剥离量
