    // v24.76：★ 站点「报价方案」里的国家中文名与常用简称常常不是一回事 ——
    //   实测（458客户报价方案_12071条_20260905015215.csv）有 10 个名字在 COUNTRY_CODE_MAP 里查不到：
    //   阿拉伯联合酋长国 81 条 / 卢旺达 157 / 波多黎各 48 / 台灣 10 / 香港 10 /
    //   马约特 6 / 马达加斯加 6 / 留尼汪岛 6 / 俄罗斯联邦 6 / 摩纳哥 2
    //   而 normalizeCountry 原来「查不到就原样透传」→ 报价接口收到 country_code=阿拉伯联合酋长国 → 后端 **0 条**
    //   → 用户看到的「阿拉伯联合酋长国一直查不到」（汇总里匹配方案数=0）。
    const COUNTRY_NAME_ALIAS = {
        '阿拉伯联合酋长国': 'AE', '阿拉伯酋长联合国': 'AE',
        '俄罗斯联邦': 'RU', '大韩民国': 'KR', '朝鲜民主主义人民共和国': 'KP',
        '台湾': 'TW', '台灣': 'TW', '台湾省': 'TW', '台湾地区': 'TW',
        '香港': 'HK', '香港特别行政区': 'HK',
        '澳门': 'MO', '澳门特别行政区': 'MO',
        '卢旺达': 'RW', '波多黎各': 'PR', '摩纳哥': 'MC', '马达加斯加': 'MG',
        '马约特': 'YT', '留尼汪': 'RE', '留尼汪岛': 'RE',
        '东帝汶': 'TL', '格陵兰': 'GL', '法属波利尼西亚': 'PF', '百慕大': 'BM',
        '开曼群岛': 'KY', '佛得角': 'CV', '冈比亚': 'GM', '多哥': 'TG', '贝宁': 'BJ',
        '布基纳法索': 'BF', '马里': 'ML', '几内亚': 'GN', '塞拉利昂': 'SL', '利比里亚': 'LR',
        '刚果金': 'CD', '刚果布': 'CG', '尼日尔': 'NE', '吉布提': 'DJ', '索马里': 'SO',
        '厄立特里亚': 'ER', '马拉维': 'MW', '莱索托': 'LS', '斯威士兰': 'SZ',
        // v24.77：站点在少数国家名后面带中文括号（实测用户 小测试.xlsx 里「阿塞拜疆(独联体)」1 行 → 报价 0 条）
        '阿塞拜疆(独联体)': 'AZ', '阿塞拜疆（独联体）': 'AZ',
        '刚果(金)': 'CD', '刚果（金）': 'CD', '刚果(布)': 'CG', '刚果（布）': 'CG'
    };
    // v24.76：站点国家表（/api/country）的动态索引 —— 站点叫什么名字都能反查回 ISO 代码，
    //   不必每出现一个新写法就来改静态表（静态表只作兜底，网络不可用时仍能用）
    let _countryAliasIndex = null;
    let _countryAliasLoading = null;
    function countryAliasKey(s) { return String(s == null ? '' : s).replace(/[\s\u3000]/g, '').toLowerCase(); }
    function _countryAliasPut(map, name, code) {
        const key = countryAliasKey(name);
        const cc = String(code == null ? '' : code).trim();
        if (!key || !/^[A-Za-z]{2}$/.test(cc)) return;
        if (!map[key]) map[key] = cc.toUpperCase();
    }
    function ensureCountryAlias(list) {
        if (!_countryAliasIndex) _countryAliasIndex = {};
        (list || []).forEach(c => {
            if (!c) return;
            const code = c.code || c.country_code || c.iso_code || '';
            _countryAliasPut(_countryAliasIndex, c.chinese_name, code);
            _countryAliasPut(_countryAliasIndex, c.name, code);
            _countryAliasPut(_countryAliasIndex, c.cn_name, code);
        });
        return _countryAliasIndex;
    }
    // 尽力预取国家表（批量匹配 / 亏本分析等不走面板的路径用）；失败不影响主流程
    function prefetchCountryAlias() {
        if (_countryAliasIndex && Object.keys(_countryAliasIndex).length) return Promise.resolve(_countryAliasIndex);
        if (_countryAliasLoading) return _countryAliasLoading;
        _countryAliasLoading = (async () => {
            try { return ensureCountryAlias(await fetchCountryList()); }
            catch (e) { return _countryAliasIndex || {}; }
        })();
        _countryAliasLoading.then(() => { _countryAliasLoading = null; }, () => { _countryAliasLoading = null; });
        return _countryAliasLoading;
    }
    // 国家值 → ISO 两位代码；已是两位字母则原样大写；未识别则原样返回（由调用方提示）
    // v24.76：查找顺序 = 静态表 → 别名表 → 站点国家表动态索引 → 去尾缀（联邦/共和国/岛/特别行政区）再查
    function normalizeCountry(val) {
        const v = String(val || '').trim();
        if (!v) return '';
        if (/^[A-Za-z]{2}$/.test(v)) return v.toUpperCase();
        // 「中文名 (AE)」/「中文名（AE）」整串
        const pm = /^(.*?)[\s\u3000]*[（(]\s*([A-Za-z]{2})\s*[)）]$/.exec(v);
        if (pm && pm[1]) {
            const inner = normalizeCountry(pm[1]);
            return /^[A-Za-z]{2}$/.test(inner) ? inner : pm[2].toUpperCase();
        }
        const look = (s) => {
            const raw = String(s == null ? '' : s).replace(/[\s\u3000]/g, '');
            if (!raw) return '';
            // 去空格版 + 原样版都试：静态表的英文键里带空格（'united arab emirates'），
            //   只查去空格版会漏（实测回落成原值 → 又变成 0 条）
            const src = String(s == null ? '' : s).trim().toLowerCase();
            return COUNTRY_CODE_MAP[raw.toLowerCase()] || COUNTRY_CODE_MAP[src]
                || COUNTRY_NAME_ALIAS[raw] || COUNTRY_NAME_ALIAS[String(s == null ? '' : s).trim()]
                || (_countryAliasIndex && (_countryAliasIndex[countryAliasKey(raw)] || _countryAliasIndex[src])) || '';
        };
        let hit = look(v);
        if (hit) return hit;
        const flat = String(v).replace(/[\s\u3000]/g, '');
        // v24.77：带中文括号的国家名（阿塞拜疆(独联体) / 刚果（金））——
        //   上面只处理了「名字 (XX)」两位代码形态，括号里是中文时要在这一层兜底：
        //   ① 去掉括号及其内容再查（阿塞拜疆(独联体) → 阿塞拜疆）
        //   ② 只去掉括号符号再查（刚果（金）→ 刚果金）
        const mParen = /^(.*?)[（(][^）)]*[)）]$/.exec(flat);
        if (mParen && mParen[1]) { hit = look(mParen[1]); if (hit) return hit; }
        const noParen = flat.replace(/[（()）]/g, '');
        if (noParen !== flat) { hit = look(noParen); if (hit) return hit; }
        // 去尾缀再查（俄罗斯联邦 → 俄罗斯；香港特别行政区 → 香港；留尼汪岛 → 留尼汪）
        const stripped = flat.replace(/(人民共和国|民主共和国|联邦共和国|共和国|联邦|王国|联合酋长国|特别行政区|群岛|岛|地区)$/, '');
        if (stripped && stripped !== flat) {
            hit = look(stripped);
            if (hit) return hit;
        }
        return v;
    }

    // v23.3：带样式的 Excel 导出库（xlsx-js-style，支持单元格样式）
    const XLSX_STYLE_CDNS = [
        'https://cdn.jsdelivr.net/npm/xlsx-js-style@1.2.0/dist/xlsx.min.js',
        'https://unpkg.com/xlsx-js-style@1.2.0/dist/xlsx.min.js'
    ];
    let _xlsxStyleLib = null;
    function loadXlsxStyleLib() {
        if (_xlsxStyleLib) return Promise.resolve(true);
        return new Promise(resolve => {
            let idx = 0;
            let settled = false;
            const done = (ok) => {
                if (!settled) {
                    settled = true;
                    // v23.4：xlsx-js-style 全局变量为 _win.XLSX（与标准 SheetJS 同名，后者会覆盖前者）
                    _xlsxStyleLib = ok ? (_win.XLSX || null) : null;
                    resolve(!!_xlsxStyleLib);
                }
            };
            const tryNext = () => {
                if (idx >= XLSX_STYLE_CDNS.length) { done(false); return; }
                const s = document.createElement('script');
                s.src = XLSX_STYLE_CDNS[idx++];
                const timer = setTimeout(() => { s.remove(); tryNext(); }, 8000);
                s.onload = () => { clearTimeout(timer); done(true); };
                s.onerror = () => { clearTimeout(timer); tryNext(); };
                document.head.appendChild(s);
            };
            tryNext();
        });
    }

    function loadXlsxLib() {
        if (_win.XLSX) { _xlsxLib = _win.XLSX; return Promise.resolve(true); }
        return new Promise(resolve => {
            let idx = 0;
            let settled = false;
            const done = (ok) => {
                if (!settled) {
                    settled = true;
                    _xlsxLib = ok ? (_win.XLSX || null) : null;
                    resolve(!!_xlsxLib);
                }
            };
            const tryNext = () => {
                if (idx >= XLSX_CDNS.length) { done(false); return; }
                const s = document.createElement('script');
                s.src = XLSX_CDNS[idx++];
                // 超时保护：CDN 被静默拦截（既不报错也不加载）时不再无限等待
                const timer = setTimeout(() => { s.remove(); tryNext(); }, 8000);
                s.onload = () => { clearTimeout(timer); done(true); };
                s.onerror = () => { clearTimeout(timer); tryNext(); };
                document.head.appendChild(s);
            };
            tryNext();
        });
    }
    function parseCsv(text) {
        if (text.charCodeAt(0) === 0xFEFF) text = text.slice(1);
        const rows = [];
        let row = [], cell = '', inQuotes = false;
        for (let i = 0; i < text.length; i++) {
            const c = text[i];
            if (inQuotes) {
                if (c === '"') {
                    if (text[i + 1] === '"') { cell += '"'; i++; } else inQuotes = false;
                } else cell += c;
            } else if (c === '"') {
                inQuotes = true;
            } else if (c === ',') {
                row.push(cell); cell = '';
            } else if (c === '\n') {
                row.push(cell); rows.push(row); row = []; cell = '';
            } else if (c !== '\r') {
                cell += c;
            }
        }
        if (cell !== '' || row.length) { row.push(cell); rows.push(row); }
        return rows.filter(r => r.some(v => String(v).trim() !== ''));
    }
    function readFileAsText(file) {
        return new Promise((resolve, reject) => {
            const r = new FileReader();
            r.onload = () => resolve(r.result);
            r.onerror = () => reject(r.error);
            r.readAsText(file);
        });
    }
    function readFileAsArrayBuffer(file) {
        return new Promise((resolve, reject) => {
            const r = new FileReader();
            r.onload = () => resolve(r.result);
            r.onerror = () => reject(r.error);
            r.readAsArrayBuffer(file);
        });
    }
    async function parseExcelFile(file) {
        const name = (file.name || '').toLowerCase();
        if (name.endsWith('.csv')) {
            return parseCsv(await readFileAsText(file));
        }
        const ok = await loadXlsxLib();
        if (!ok || !_xlsxLib) throw new Error('无法加载 xlsx 解析库（CDN 被拦截或超时），请把文件另存为 .csv 后重试');
        const buf = await readFileAsArrayBuffer(file);
        const wb = _xlsxLib.read(buf, { type: 'array' });
        const ws = wb.Sheets[wb.SheetNames[0]];
        return _xlsxLib.utils.sheet_to_json(ws, { header: 1, defval: '' })
            .filter(r => Array.isArray(r) && r.some(v => String(v).trim() !== ''));
    }
    function pickColumn(headers, keywords) {
        for (const kw of keywords) {
            for (let i = 0; i < headers.length; i++) {
                const v = String(headers[i]).trim().toLowerCase();
                if (v === kw.toLowerCase() || v.includes(kw.toLowerCase())) return i;
            }
        }
        return -1;
    }
    // 从最近一次列表请求的 URL 里还原系统搜索面板用的真实过滤参数
    // 实测（erp.shipbear.co）：
    //   计款码过滤 = product_code（模糊/包含） + product_code_exact（精确）成对出现
    //   国家过滤   = country_code
    //   其它面板默认过滤（is_active=true、effective_period_from_after=2020-01-01、ordering 等）随 baseUrl 一并保留
    function sniffParams() {
        const res = { country: 'country_code', codeFuzzy: 'product_code', codeExact: 'product_code_exact', store: 'store_code', matchMode: 'exact' };
        if (!_meta.lastUrl) return res;
        try {
            const u = new URL(_meta.lastUrl);
            u.searchParams.forEach((_, k) => {
                const lk = k.toLowerCase();
                if (lk.includes('page')) return;
                if (lk.includes('store')) { res.store = k; return; }   // v24.73：店铺ID参数名
                if (lk.includes('country')) res.country = k;
                else if (lk === 'product_code_exact' || lk === 'code_exact' || lk === 'qpn_exact') res.codeExact = k;
                else if (lk.includes('product') || lk === 'code' || lk === 'qpn' || lk.includes('qpn')) res.codeFuzzy = k;
            });
            // 最近一次搜索实际用了哪个参数，就推断匹配方式
            if (u.searchParams.get(res.codeExact)) res.matchMode = 'exact';
            else if (u.searchParams.get(res.codeFuzzy)) res.matchMode = 'fuzzy';
        } catch (e) {}
        return res;
    }
    // 构造本次查询的国家/计款码参数对：匹配方式选定的参数填值，另一个参数显式清空（与系统面板行为一致）
    function buildFilterParams(country, code, storeOverride) {
        const st = _batchState;
        const params = [];
        // v24.76：店铺过滤三级优先 —— 上传表「客户ID」列（逐行，storeOverride）→ 面板「客户(店铺ID)过滤」输入 → 不过滤
        //   （v24.73/75 只有「一个整批生效的值」→ 一批里含多个客户时没法逐行指定，用户实测的痛点）
        const _scRow = (storeOverride == null) ? '' : String(storeOverride).trim();
        const _scUse = _scRow || String(st.storeCode || '').trim();
        if (_scUse && (st.storeParam || 'store_code')) params.push([st.storeParam || 'store_code', _scUse]);
        if (country) params.push([st.countryParam, country]);
        if (st.matchMode === 'fuzzy') {
            if (st.codeParamFuzzy && code) params.push([st.codeParamFuzzy, code]);
            if (st.codeParamExact) params.push([st.codeParamExact, '']);
        } else {
            if (st.codeParamExact && code) params.push([st.codeParamExact, code]);
            if (st.codeParamFuzzy) params.push([st.codeParamFuzzy, '']);
        }
        return params;
    }
    function buildListBase() {
        if (!_meta.lastUrl) return '';
        try {
            const u = new URL(_meta.lastUrl);
            // 保留搜索面板的其它过滤条件（status/is_active/ordering/effective_period_from_after 等），
            // 去掉分页参数和由本脚本自行控制的查询参数
            ['page', 'page_size'].forEach(k => u.searchParams.delete(k));
            [(_batchState.countryParam || ''), (_batchState.codeParamFuzzy || ''), (_batchState.codeParamExact || ''),
            (_batchState.storeParam || 'store_code'), 'store_code']
                .forEach(k => { if (k) u.searchParams.delete(k); });   // v24.73：店铺参数也由本脚本控制（避免继承页面残留）
            return u.toString();
        } catch (e) { return ''; }
    }
    async function fetchPair(country, code, store) {
        const rows = [];
        const filterParams = buildFilterParams(country, code, store);
        let page = 1;
        while (true) {
            const url = new URL(_batchState.baseUrl);
            filterParams.forEach(([k, v]) => url.searchParams.set(k, v));
            url.searchParams.set('page', page);
            url.searchParams.set('page_size', EXPORT_PAGE_SIZE);
            let data = null;
            for (let a = 1; a <= EXPORT_MAX_RETRY; a++) {
                try {
                    const init = { credentials: 'include', cache: 'no-store', headers: buildAuthHeaders() };
                    const resp = await originalFetch(url.toString(), init);
                    if (resp.status === 401) {
                        // v23.67：先主动调 refresh 换新 token（无需刷新页面），用新 token 重试
                        if (a < EXPORT_MAX_RETRY) {
                            const newTok = await refreshAccessToken();
                            if (newTok) continue;
                            await sleep(3000);
                            if (getFreshBearerToken()) continue;
                        }
                        const err = new Error('登录已过期(401)：token 有效期约20分钟，请刷新页面（无需重新登录）后点「开始批量匹配」续传');
                        err.noRetry = true;
                        throw err;
                    }
                    if (!resp.ok) throw new Error('HTTP ' + resp.status);
                    data = await resp.json();
                    break;
                } catch (e) {
                    if (e && e.noRetry) throw e;
                    if (a === EXPORT_MAX_RETRY) throw e;
                    await sleep(EXPORT_DELAY * a * 3);
                }
            }
            if (!data || !Array.isArray(data.results) || data.results.length === 0) break;
            rows.push(...data.results.map(normalizeQuotation));
            const totalPages = data.total_pages || Math.ceil((data.count || 0) / EXPORT_PAGE_SIZE);
            if (page >= totalPages) break;
            page++;
            await sleep(EXPORT_DELAY);
        }
        return rows;
    }
    async function saveBatchPair(fileKey, p, schemes) {
        try {
            await idbPut({ id: 'batch_' + fileKey + '::' + encodeURIComponent(p.key), country: p.country, code: p.code, rows: schemes });
        } catch (e) {}
    }
    async function saveBatchMeta() {
        const st = _batchState;
        try {
            await idbPut({
                id: 'batch_' + st.fileKey,
                fileKey: st.fileKey,
                baseUrl: st.baseUrl,
                countryParam: st.countryParam, codeParamFuzzy: st.codeParamFuzzy, codeParamExact: st.codeParamExact,
                matchMode: st.matchMode,
                includeUnmatched: st.includeUnmatched,
                inspectionMode: st.inspectionMode,
                exportHash: st.exportHash,
                countryIdx: st.countryIdx, codeIdx: st.codeIdx,
                pairCount: st.pairOrder.length,
                donePairs: st.donePairs,
                finished: false, updated: Date.now()
            });
        } catch (e) {}
    }
    async function loadBatchExisting(fileKey) {
        const existing = new Map();
        try {
            const all = await idbGetAll();
            for (const r of all) {
                if (typeof r.id === 'string' && r.id.startsWith('batch_' + fileKey + '::') && Array.isArray(r.rows)) {
                    const key = decodeURIComponent(r.id.split('::').slice(1).join('::'));
                    existing.set(key, r.rows);
                }
            }
        } catch (e) {}
        return existing;
    }
    async function clearBatchData(fileKey) {
        try {
            const all = await idbGetAll();
            const ids = all
                .filter(r => typeof r.id === 'string' && r.id.startsWith('batch_' + fileKey))
                .map(r => r.id);
            if (ids.length) await idbDelete(ids);
        } catch (e) {}
    }
    function appendBatchLog(msg) {
        if (!_batchPanel) return;
        const log = _batchPanel.querySelector('#batch-log');
        if (!log) return;
        log.textContent += msg + '\n';
        log.scrollTop = log.scrollHeight;
    }
    function updateBatchPanel() {
        if (!_batchPanel) return;
        const st = _batchState;
        const bar = _batchPanel.querySelector('#batch-bar');
        const prog = _batchPanel.querySelector('#batch-progress');
        const pct = st.pairOrder.length ? Math.round(st.donePairs / st.pairOrder.length * 100) : 0;
        if (bar) bar.style.width = pct + '%';
        if (prog) {
            const elapsed = (Date.now() - st.startTime) / 1000;
            const avg = st.donePairs ? elapsed / st.donePairs : 0;
            const remain = st.donePairs ? Math.ceil((st.pairOrder.length - st.donePairs) * avg) : 0;
            prog.textContent = '已处理 ' + st.donePairs + ' / ' + st.pairOrder.length + ' 个国家×计款码组合'
                + '（匹配到 ' + st.matchedRows.toLocaleString() + ' 条方案'
                + (st.includeUnmatched ? '，无匹配 ' + st.unmatchedRows + ' 组' : '') + '）'
                + (remain > 0 ? '，预计剩余约 ' + Math.ceil(remain / 60) + ' 分钟' : '');
        }
    }
