        $('#batch-code-col').addEventListener('change', e => { _batchState.codeIdx = parseInt(e.target.value, 10); });
        // v24.76：客户ID列（-1 = 不使用，整批用「客户(店铺ID)过滤」输入框）
        if ($('#batch-store-col')) $('#batch-store-col').addEventListener('change', e => { _batchState.storeIdx = parseInt(e.target.value, 10); });
        $('#batch-country-param').addEventListener('change', e => { _batchState.countryParam = e.target.value.trim() || 'country_code'; });
        $('#batch-code-param-exact').addEventListener('change', e => { _batchState.codeParamExact = e.target.value.trim() || 'product_code_exact'; });
        $('#batch-code-param-fuzzy').addEventListener('change', e => { _batchState.codeParamFuzzy = e.target.value.trim() || 'product_code'; });
        $('#batch-match-mode').addEventListener('change', e => { _batchState.matchMode = e.target.value; });
        // v24.73：店铺ID过滤（取值 + 参数名）
        $('#batch-store-code').addEventListener('change', e => { _batchState.storeCode = String(e.target.value || '').trim(); });
        $('#batch-store-param').addEventListener('change', e => { _batchState.storeParam = String(e.target.value || '').trim() || 'store_code'; });
        $('#batch-import').onclick = () => importLastSearchParams();
        $('#batch-unmatched').addEventListener('change', e => { _batchState.includeUnmatched = e.target.checked; });
