        const panel = document.createElement('div');
        panel.style.cssText = 'background:#fff;border-radius:10px;padding:18px 20px;width:900px;max-width:96%;max-height:92vh;overflow-y:auto;box-shadow:0 6px 24px rgba(0,0,0,0.28);font:14px/1.6 system-ui,sans-serif;color:#262626;';
